    return {"refId": ref, "datasource": P, "instant": True, "range": False, "format": "table", "expr": expr}


def order(labels):
    parts = []
    for i, s in enumerate(["investigate", "unknown", "matched"], 1):
        parts.append("(max by (%s)(%s)*0+%d)" % (labels, lo("work_status", ',status="%s"' % s), i))
    return " or ".join(parts)


A1 = order("run, scenario, status_text")
A3 = order("run, scenario, status_text, owner, next_step")
stat_map = [{"type": "value", "options": {
    "成功": {"text": "成功", "color": "green", "index": 0},
    "失敗": {"text": "失敗", "color": "red", "index": 1},
    "紀錄不全": {"text": "紀錄不全", "color": "#808080", "index": 2}}}]


